package main

import(
	"crypto/tls"
	"crypto/x509"
	"flag"
	"fmt"
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"
	mqtt "github.com/eclipse/paho.mqtt.golang"
	"github.com/paulohspdev-cmyk/ProjetoGerador/gateway-umbrella/adapters/internal/wire"
)
type inbound struct{payload []byte;topic string;qos byte;retained bool;duplicate bool;messageID uint16}
func main(){var id,broker,clientID,topic,userEnv,passEnv,caFile,certFile,keyFile string;var qos,queue int;flag.StringVar(&id,"id","mqtt-1","adapter id");flag.StringVar(&broker,"broker","","broker URI: tcp://, ssl://, ws:// or wss://");flag.StringVar(&clientID,"client-id","rc-gateway-umbrella","MQTT client id");flag.StringVar(&topic,"topic","#","subscription topic");flag.IntVar(&qos,"qos",1,"subscription QoS 0..2");flag.IntVar(&queue,"queue",8192,"bounded inbound queue");flag.StringVar(&userEnv,"username-env","","environment variable containing username");flag.StringVar(&passEnv,"password-env","","environment variable containing password");flag.StringVar(&caFile,"ca-file","","optional CA PEM");flag.StringVar(&certFile,"client-cert","","optional mTLS client cert PEM");flag.StringVar(&keyFile,"client-key","","optional mTLS client key PEM");flag.Parse();if broker==""{fatal("-broker is required")};if qos<0||qos>2{fatal("qos must be 0..2")};if queue<1{fatal("queue must be >0")};if (certFile=="")!=(keyFile==""){fatal("client-cert and client-key must be supplied together")};out:=wire.NewWriter(os.Stdout);messages:=make(chan inbound,queue);fatalCh:=make(chan error,1);opts:=mqtt.NewClientOptions().AddBroker(broker).SetClientID(clientID);opts.SetAutoReconnect(true);opts.SetConnectRetry(true);opts.SetCleanSession(false);opts.SetOrderMatters(false);opts.SetKeepAlive(20*time.Second);opts.SetPingTimeout(10*time.Second);if userEnv!=""{u:=os.Getenv(userEnv);if u==""{fatal("username env is empty")};opts.SetUsername(u)};if passEnv!=""{p:=os.Getenv(passEnv);if p==""{fatal("password env is empty")};opts.SetPassword(p)};if strings.HasPrefix(broker,"ssl://")||strings.HasPrefix(broker,"tls://")||strings.HasPrefix(broker,"wss://")||caFile!=""||certFile!=""{cfg,err:=tlsConfig(caFile,certFile,keyFile);if err!=nil{fatal(err.Error())};opts.SetTLSConfig(cfg)};handler:=func(_ mqtt.Client,msg mqtt.Message){item:=inbound{payload:append([]byte(nil),msg.Payload()...),topic:msg.Topic(),qos:msg.Qos(),retained:msg.Retained(),duplicate:msg.Duplicate(),messageID:msg.MessageID()};select{case messages<-item:default:select{case fatalCh<-fmt.Errorf("MQTT inbound queue saturated (%d); refusing silent data loss",queue):default:}}};opts.SetDefaultPublishHandler(handler);opts.OnConnect=func(c mqtt.Client){token:=c.Subscribe(topic,byte(qos),handler);if !token.WaitTimeout(15*time.Second){select{case fatalCh<-fmt.Errorf("MQTT subscribe timeout for %s",topic):default:};return};if err:=token.Error();err!=nil{select{case fatalCh<-fmt.Errorf("MQTT subscribe: %w",err):default:}}};opts.OnConnectionLost=func(_ mqtt.Client,err error){fmt.Fprintf(os.Stderr,"mqtt connection lost: %v\n",err)};client:=mqtt.NewClient(opts);token:=client.Connect();if !token.WaitTimeout(30*time.Second){fatal("MQTT connect timeout")};if err:=token.Error();err!=nil{fatal(fmt.Sprintf("MQTT connect: %v",err))};signals:=make(chan os.Signal,1);signal.Notify(signals,syscall.SIGINT,syscall.SIGTERM);for{select{case<-signals:client.Disconnect(1000);return;case err:=<-fatalCh:client.Disconnect(250);fatal(err.Error());case msg:=<-messages:meta:=map[string]any{"topic":msg.topic,"qos":msg.qos,"retained":msg.retained,"duplicate":msg.duplicate,"messageId":msg.messageID,"clientId":clientID,"readOnly":true};if err:=out.EmitBytes(wire.Message{Kind:"observation",SessionID:id,Transport:"mqtt",RemoteAddr:broker,Protocol:"mqtt",Meta:meta},msg.payload);err!=nil{client.Disconnect(250);fatal(fmt.Sprintf("stdout: %v",err))}}}}
func tlsConfig(caFile,certFile,keyFile string)(*tls.Config,error){cfg:=&tls.Config{MinVersion:tls.VersionTLS13};if caFile!=""{raw,err:=os.ReadFile(caFile);if err!=nil{return nil,err};pool:=x509.NewCertPool();if !pool.AppendCertsFromPEM(raw){return nil,fmt.Errorf("unable to parse CA PEM")};cfg.RootCAs=pool};if certFile!=""{cert,err:=tls.LoadX509KeyPair(certFile,keyFile);if err!=nil{return nil,err};cfg.Certificates=[]tls.Certificate{cert}};return cfg,nil}
func fatal(msg string){fmt.Fprintln(os.Stderr,msg);os.Exit(1)}
